INSERT INTO DimAccount (SK_AccountID, AccountID, SK_BrokerID, SK_CustomerID, Status, AccountDesc, TaxStatus, IsCurrent, BatchID, EffectiveDate, EndDate) WITH Accounts AS (SELECT Acc.CA_ID AS AccountID, Br.SK_BrokerID AS SK_BrokerID, DimC.SK_CustomerID AS SK_CustomerID, Acc.Customer_Id AS Customer_Id, Acc.CA_NAME AS AccountDesc, TRY_CAST(Acc.CA_TAX_ST AS INT) AS TaxStatus, Act.ActionType AS ActionType, TRY_CAST(Act.ActionTS AS TIMESTAMP) AS ActionTS FROM Source.CustomerXML AS C INNER JOIN Source.ActionXML AS Act ON C.Action_Id = Act.Action_Id INNER JOIN Source.AccountXML AS Acc ON C.Customer_Id = Acc.Customer_Id INNER JOIN DimBroker AS Br ON TRY_CAST(Acc.CA_B_ID AS INT) = Br.BrokerID INNER JOIN DimCustomer AS DimC ON C.C_ID = DimC.CustomerID WHERE TRY_CAST(Act.ActionTS AS TIMESTAMP) >= DimC.EffectiveDate AND TRY_CAST(Act.ActionTS AS TIMESTAMP) <= DimC.EndDate), AccountsNewAndAddAcct AS (SELECT *, 'ACTIVE' AS Status FROM Accounts WHERE ActionType IN ('NEW', 'ADDACCT')), AccountsUpd AS (SELECT * FROM Accounts WHERE ActionType = 'UPDACCT'), AccountsCloseAcct AS (SELECT Acc.CA_ID AS AccountID, TRY_CAST(Act.ActionTS AS TIMESTAMP) AS ActionTS FROM Source.AccountXML AS Acc INNER JOIN Source.CustomerXML AS C ON C.Customer_Id = Acc.Customer_Id INNER JOIN Source.ActionXML AS Act ON C.Action_Id = Act.Action_Id WHERE Act.ActionType = 'CLOSEACCT'), AccountsNewAndAddAcctAndUpd AS (SELECT AccountID, SK_BrokerID, SK_CustomerID, 'ACTIVE' AS Status, AccountDesc, TaxStatus, ActionTS, ActionType FROM AccountsNewAndAddAcct UNION ALL SELECT UpdAcct.AccountID, COALESCE(UpdAcct.SK_BrokerID, NewAcct.SK_BrokerID) AS SK_BrokerID, COALESCE(UpdAcct.SK_CustomerID, NewAcct.SK_CustomerID) AS SK_CustomerID, NewAcct.Status AS Status, COALESCE(UpdAcct.AccountDesc, NewAcct.AccountDesc) AS AccountDesc, COALESCE(UpdAcct.TaxStatus, NewAcct.TaxStatus) AS TaxStatus, UpdAcct.ActionTS, UpdAcct.ActionType FROM AccountsNewAndAddAcct AS NewAcct INNER JOIN AccountsUpd AS UpdAcct ON NewAcct.AccountID = UpdAcct.AccountID), AccountsFinal AS (SELECT * FROM AccountsNewAndAddAcctAndUpd UNION ALL SELECT AcctNewUpd.AccountID, SK_BrokerID, SK_CustomerID, 'INACTIVE' AS Status, AccountDesc, TaxStatus, AcctNewUpd.ActionTS, 'CLOSEACCT' AS ActionType FROM AccountsNewAndAddAcctAndUpd AS AcctNewUpd INNER JOIN AccountsCloseAcct AS AcctClose ON AcctNewUpd.AccountID = AcctClose.AccountID INNER JOIN (SELECT AccountID, MAX(ActionTS) AS ActionTSLatestAccount FROM AccountsNewAndAddAcctAndUpd GROUP BY AccountID) AS LastAcct ON AcctNewUpd.AccountID = LastAcct.AccountID AND AcctNewUpd.ActionTS = LastAcct.ActionTSLatestAccount) SELECT ROW_NUMBER() OVER (ORDER BY AccountID, ActionTS ASC) AS SK_AccountID, AccountID, SK_BrokerID, SK_CustomerID, Status, AccountDesc, TaxStatus, CASE WHEN LEAD(ActionTS) OVER (PARTITION BY AccountID ORDER BY ActionTS ASC) IS NULL THEN TRUE ELSE FALSE END AS IsCurrent, 1 AS BatchID, ActionTS AS EffectiveDate, COALESCE(LEAD(ActionTS) OVER (PARTITION BY AccountID ORDER BY ActionTS ASC), CAST('9999-12-31 00:00:00' AS TIMESTAMP)) AS EndDate FROM AccountsFinal ORDER BY AccountID, ActionTS ASC;
